-- ========================================================
-- DATABASE FITUR KEBIJAKAN & SISTEM EKONOMI DUNIA
-- File: d:\project-sendiri\em\json\database_sistem_ekonomi\database_sistem_ekonomi.sql
-- Description: Menyimpan data nilai spektrum sistem ekonomi (0-100), kartu kebijakan terpilih,
--              dan statistik indikator ekonomi untuk 207 negara.
-- ========================================================

DROP TABLE IF EXISTS `database_sistem_ekonomi`;
CREATE TABLE IF NOT EXISTS `database_sistem_ekonomi` (
    id INT AUTO_INCREMENT PRIMARY KEY,
    country_id INT NOT NULL,
    country_slug VARCHAR(100) NOT NULL,
    country_name VARCHAR(100) NOT NULL,
    iso VARCHAR(10) NOT NULL,
    spektrum_val INT NOT NULL DEFAULT 50, -- 0 (Terpusat/Komando) - 100 (Pasar Bebas/Laissez-Faire)
    system_title VARCHAR(100) NOT NULL,
    category ENUM('Terpusat', 'Campuran', 'Pasar Bebas') NOT NULL,
    policy_price_control ENUM('Terpusat', 'Pasar Bebas') NOT NULL DEFAULT 'Terpusat',
    policy_strategic_ownership ENUM('Terpusat', 'Pasar Bebas') NOT NULL DEFAULT 'Terpusat',
    policy_trade ENUM('Terpusat', 'Pasar Bebas') NOT NULL DEFAULT 'Pasar Bebas',
    policy_labor ENUM('Terpusat', 'Pasar Bebas') NOT NULL DEFAULT 'Pasar Bebas'
);

